<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Composition with Red, Blue and Yellow — Piet Mondrian, 1930</title>
<meta name="description" content="Piet Mondrian's Composition with Red, Blue and Yellow (1930): a De Stijl painting in oil on canvas, and why its asymmetric balance still matters.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Archivo:wght@400;600;800;900&display=swap" rel="stylesheet">
<style>
  :root{
    --white:#ffffff;
    --ink:#0a0a0a;
    --red:#d6001c;
    --blue:#1f4c96;
    --yellow:#f7c600;
    --line:10px;
    --font:'Archivo',system-ui,sans-serif;
  }
  *{margin:0;padding:0;box-sizing:border-box}
  html{scroll-behavior:smooth}
  body{
    font-family:var(--font);
    background:var(--white);
    color:var(--ink);
    line-height:1.55;
    -webkit-font-smoothing:antialiased;
  }
  ::selection{background:var(--yellow);color:var(--ink)}
  a{color:inherit}
  canvas#bg{position:fixed;inset:0;width:100%;height:100%;z-index:-1;opacity:.5}

  .wrap{max-width:1120px;margin:0 auto;padding:0 24px}

  header{
    display:flex;justify-content:space-between;align-items:center;
    padding:20px 24px;border-bottom:var(--line) solid var(--ink);
    background:var(--white);position:sticky;top:0;z-index:10;
  }
  .brand{font-weight:900;letter-spacing:-0.02em;font-size:1.05rem}
  .brand i{font-style:normal;display:inline-block;width:.7em;height:.7em;margin-left:.15em}
  .brand .r{background:var(--red)} .brand .b{background:var(--blue)} .brand .y{background:var(--yellow)}
  header nav a{font-weight:600;text-decoration:none;font-size:.95rem}
  header nav a:hover{box-shadow:0 3px 0 var(--red)}

  /* hero */
  .hero{display:grid;grid-template-columns:minmax(320px,5fr) minmax(300px,4fr);gap:56px;align-items:center;padding:72px 0 88px}
  h1{font-weight:900;letter-spacing:-0.03em;line-height:1.02;font-size:clamp(2.4rem,5.2vw,4.6rem)}
  h1 .c-r{color:var(--red)} h1 .c-b{color:var(--blue)} h1 .c-y{color:#b58f00}
  .meta{margin-top:20px;font-size:1.15rem;font-weight:600}
  .meta span{display:inline-block;padding:2px 10px;margin:4px 6px 0 0;border:3px solid var(--ink)}
  .meta .m-year{background:var(--yellow)}
  .lede{margin-top:22px;max-width:52ch;font-size:1.08rem}
  .scroll-cue{margin-top:34px;display:inline-block;font-weight:800;text-decoration:none;
    border:var(--line) solid var(--ink);padding:12px 22px;background:var(--white);
    transition:transform .15s ease, box-shadow .15s ease}
  .scroll-cue:hover{transform:translate(-3px,-3px);box-shadow:6px 6px 0 var(--ink)}

  /* the painting, rebuilt in CSS */
  .painting{
    aspect-ratio:1/1;background:var(--ink);
    display:grid;gap:var(--line);
    grid-template-columns:1.15fr 1.95fr;
    grid-template-rows:2.35fr 0.95fr;
    border:var(--line) solid var(--ink);
    box-shadow:14px 14px 0 rgba(10,10,10,.12);
    will-change:transform;
  }
  .painting div{transform:scale(.92);opacity:0;animation:block-in .7s cubic-bezier(.2,.8,.2,1) forwards}
  .p-white{background:var(--white);animation-delay:.05s}
  .p-red{background:var(--red);animation-delay:.35s}
  .p-blue{background:var(--blue);animation-delay:.6s}
  .p-yellow{background:var(--yellow);animation-delay:.8s}
  @keyframes block-in{to{transform:scale(1);opacity:1}}
  .caption{margin-top:14px;font-size:.85rem;font-weight:600;color:#333}

  /* sections */
  section{border-top:var(--line) solid var(--ink);padding:72px 0;scroll-margin-top:110px}
  .grid2{display:grid;grid-template-columns:1fr 1.4fr;gap:48px}
  h2{font-weight:900;letter-spacing:-0.02em;font-size:clamp(1.7rem,3.2vw,2.6rem);line-height:1.05}
  h2 .tag{display:inline-block;width:.55em;height:.55em;margin-right:.18em;vertical-align:baseline}
  .t-red{background:var(--red)} .t-blue{background:var(--blue)} .t-yellow{background:var(--yellow)} 
